public class InnerGatewayTargetTargetConfigurationFactory(Action<Humidifier.BedrockAgentCore.GatewayTargetTypes.TargetConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTargetTypes.TargetConfiguration>
{

    internal InnerGatewayTargetInferenceTargetConfigurationFactory InferenceFactory { get; set; }

    internal InnerGatewayTargetHttpTargetConfigurationFactory HttpFactory { get; set; }

    internal InnerGatewayTargetMcpTargetConfigurationFactory McpFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTargetTypes.TargetConfiguration Create()
    {
        var targetConfigurationResult = CreateTargetConfiguration();
        factoryAction?.Invoke(targetConfigurationResult);

        return targetConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTargetTypes.TargetConfiguration CreateTargetConfiguration()
    {
        var targetConfigurationResult = new Humidifier.BedrockAgentCore.GatewayTargetTypes.TargetConfiguration();

        return targetConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTargetTypes.TargetConfiguration result)
    {
        base.CreateChildren(result);

        result.Inference ??= InferenceFactory?.Build();
        result.Http ??= HttpFactory?.Build();
        result.Mcp ??= McpFactory?.Build();
    }

} // End Of Class

